#!/usr/bin/env python3
"""Apply reviewed v0.42 delta to the verified v0.41 source, no network or personal data."""
import subprocess, base64, gzip
DATA=""
patch=gzip.decompress(base64.b64decode(DATA,validate=True))
subprocess.run(['patch','-p1','--batch','--fuzz=0'],input=patch,check=True)
print('Applied Telegram Archive 0.42 delta: '+str(len(patch))+' bytes')